/**
 * Calculates the discounted price for a customer order.
 *
 * @param {number} price the original price before any discount
 * @param {number} discountPercent the discount to apply, between 0 and 100
 * @returns {number} the price after the discount is applied
 * @throws {Error} if discountPercent is outside 0 to 100
 */
function applyDiscount(price, discountPercent) {
  if (discountPercent < 0 || discountPercent > 100) {
    throw new Error('discountPercent must be between 0 and 100');
  }
  return price * (1 - discountPercent / 100);
}

