const LARGE_TRANSFER_THRESHOLD = 5000;
const LARGE_TRANSFER_SURCHARGE = 250;

function processPayment(transactionAmount, total) {
  // RBI mandates an additional verification fee on transfers above the
  // threshold, to cover the cost of the extra fraud check
  if (transactionAmount > LARGE_TRANSFER_THRESHOLD) {
    total = total + LARGE_TRANSFER_SURCHARGE;
  }
  return total;
}

